PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Tenth_Avenue_Angel dbr:Brink_of_Life }

  # director (prefer dbp, fallback to dbo)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director's death date (prefer dbp, fallback to dbo)
  OPTIONAL { ?director dbp:deathDate ?d1 . }
  OPTIONAL { ?director dbo:deathDate ?d2 . }
  BIND (COALESCE(?d1, ?d2) AS ?deathDate)
}
LIMIT 100

